{
  "items": [
    {
      "name": "Finsupp.sum_ite_eq",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] [inst_2 : DecidableEq α]\n  (f : α →₀ M) (a : α) (b : α → M → N),\n  (f.sum fun x v => if a = x then b x v else 0) = if a ∈ f.support then b a (f a) else 0"
    },
    {
      "name": "Finsupp.sum_single_index",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] {a : α} {b : M}\n  {h : α → M → N}, h a 0 = 0 → (Finsupp.single a b).sum h = h a b"
    },
    {
      "name": "Finsupp.sum_eq_single",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] {f : α →₀ M} (a : α)\n  {g : α → M → N}, (∀ (b : α), f b ≠ 0 → b ≠ a → g b (f b) = 0) → (f a = 0 → g a 0 = 0) → f.sum g = g a (f a)"
    },
    {
      "name": "finsum",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "definition",
      "type": "{M : Type u_7} → {α : Sort u_8} → [AddCommMonoid M] → (α → M) → M"
    },
    {
      "name": "DFinsupp.sumZeroHom_single",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → Zero (β i)]\n  [inst_2 : AddCommMonoid γ] (φ : (i : ι) → ZeroHom (β i) γ) (i : ι) (x : β i),\n  (DFinsupp.sumZeroHom φ) (DFinsupp.single i x) = (φ i) x"
    },
    {
      "name": "DFinsupp.sum_single_index",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → Zero (β i)]\n  [inst_2 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] [inst_3 : AddCommMonoid γ] {i : ι} {b : β i}\n  {h : (i : ι) → β i → γ}, h i 0 = 0 → (DFinsupp.single i b).sum h = h i b"
    },
    {
      "name": "Finsupp.sum_fintype",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] [inst_2 : Fintype α]\n  (f : α →₀ M) (g : α → M → N), (∀ (i : α), g i 0 = 0) → f.sum g = ∑ i, g i (f i)"
    },
    {
      "name": "Finsupp.sum_ite_self_eq",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : DecidableEq α] {N : Type u_16} [inst_1 : AddCommMonoid N] (f : α →₀ N) (a : α),\n  (f.sum fun x v => if a = x then v else 0) = f a"
    }
  ]
}

